create or replace function public.admin_list_mwc_sale_admins() returns table(user_id uuid,email text,created_at timestamptz) language plpgsql security definer set search_path=public,auth as $$ begin if auth.uid() is null or not public.is_mwc_sale_admin() then raise exception 'Acesso administrativo necessário'; end if; return query select a.user_id,u.email::text,a.created_at from public.mwc_sale_admins a left join auth.users u on u.id=a.user_id order by a.created_at asc; end; $$; revoke all on function public.admin_list_mwc_sale_admins() from public,anon; grant execute on function public.admin_list_mwc_sale_admins() to authenticated; create or replace function public.admin_set_mwc_sale_admin(p_email text,p_enabled boolean) returns text language plpgsql security definer set search_path=public,auth as $$ declare v_target uuid; v_email text:=lower(trim(p_email)); v_count integer; begin if auth.uid() is null or not public.is_mwc_sale_admin() then raise exception 'Acesso administrativo necessário'; end if; if v_email is null or v_email='' then raise exception 'Informe o e-mail da conta já cadastrada'; end if; select id into v_target from auth.users where lower(email)=v_email limit 1; if v_target is null then raise exception 'Nenhuma conta cadastrada foi encontrada para esse e-mail'; end if; if p_enabled then insert into public.mwc_sale_admins(user_id) values(v_target) on conflict(user_id) do nothing; return 'authorized'; end if; if v_target=auth.uid() then raise exception 'Não é permitido remover a própria autorização nesta tela'; end if; select count(*) into v_count from public.mwc_sale_admins; if v_count<=1 then raise exception 'Não é possível remover o último administrador'; end if; delete from public.mwc_sale_admins where user_id=v_target; return 'revoked'; end; $$; revoke all on function public.admin_set_mwc_sale_admin(text,boolean) from public,anon; grant execute on function public.admin_set_mwc_sale_admin(text,boolean) to authenticated;